{
  "strategy_id": "agent_practical",
  "strategy_title": "2주 집중: 최소 RAG 시제품 구축 및 근거 추적 검증",
  "summary": "사용자의 Python 경험과 2주/주 3시간(총 6시간)의 제한된 시간을 고려하여, 이론 중심이 아닌 '코드 실행과 결과 검증'에 집중하는 로드맵입니다. LLM/RAG 기초 개념을 최소한으로 학습하고, 즉시 가상 규정 3건과 질문 5건을 처리하는 시제품을 구축합니다. 검색 성공, 근거 누락, 답변 불가 3가지 케이스를 명확히 구분하는 로직 구현에 시간을 배분하며, 유료 서비스 없이 무료 Microsoft Learn 자료와 오픈소스 도구만 활용합니다.",
  "project_goal": "가상 규정 3건에서 질문 5건의 근거를 표시하고, 근거 없는 질문은 구분하는 최소 RAG 시제품 완성",
  "total_duration_weeks": 2,
  "roadmap_flow": [
    {
      "step": 1,
      "title": "RAG 아키텍처 이해 및 환경 설정",
      "duration": "1.5h",
      "focus": "RAG의 기본 흐름(문서 분할, 임베딩, 검색, 생성) 이해 및 Python 환경에 벡터 DB 및 LLM 클라이언트 설치"
    },
    {
      "step": 2,
      "title": "가상 규정 데이터 전처리 및 인덱싱",
      "duration": "1.5h",
      "focus": "가상 규정 3건을 텍스트로 변환하고, 적절한 크기로 분할(chunking)하여 벡터 데이터베이스에 저장"
    },
    {
      "step": 3,
      "title": "검색 및 생성 파이프라인 구현",
      "duration": "1.5h",
      "focus": "질문 기반 유사도 검색 구현 및 검색된 문서를 컨텍스트로 LLM에 전달하여 답변 생성 로직 작성"
    },
    {
      "step": 4,
      "title": "근거 추적 및 예외 처리 로직 추가",
      "duration": "1.5h",
      "focus": "답변에 포함된 근거 문단 표시 기능 구현 및 검색 결과가 없거나 관련성이 낮을 때 '답변 불가'로 분류하는 로직 추가"
    }
  ],
  "milestones": [
    {
      "phase": 1,
      "phase_name": "기초 이해 및 환경 구축",
      "duration": "1주 (1.5h)",
      "focus_goal": "RAG 동작 원리 파악 및 실행 가능한 Python 환경 준비",
      "key_actions": [
        "Microsoft Learn에서 RAG 및 생성형 AI 최적화 개념 학습",
        "Python 환경에 LangChain 또는 유사 프레임워크, 벡터 DB(ChromaDB 등), LLM API 클라이언트 설치",
        "가상 규정 3건 텍스트 파일 준비"
      ],
      "deliverables": [
        "RAG 기본 흐름 다이어그램 또는 메모",
        "실행 가능한 Python 프로젝트 폴더 구조 및 requirements.txt"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 2,
      "phase_name": "데이터 전처리 및 인덱싱",
      "duration": "1주 (1.5h)",
      "focus_goal": "가상 규정 데이터를 벡터 형태로 변환하여 검색 가능한 상태로 만듦",
      "key_actions": [
        "규정 텍스트를 의미 단위로 분할(Chunking) 전략 수립 및 적용",
        "임베딩 모델 선택 및 벡터 DB에 데이터 저장",
        "검색 정확도를 위한 간단한 테스트 쿼리 실행"
      ],
      "deliverables": [
        "인덱싱된 벡터 데이터베이스",
        "데이터 전처리 스크립트"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_df219eb945ff"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 3,
      "phase_name": "RAG 파이프라인 구현",
      "duration": "1주 (1.5h)",
      "focus_goal": "질문 입력 시 관련 규정 검색 및 LLM 기반 답변 생성 기능 구현",
      "key_actions": [
        "유사도 검색(Search) 함수 구현",
        "검색 결과를 프롬프트에 포함시켜 LLM 호출",
        "질문 5건 중 3건(근거 있는 질문)에 대한 답변 생성 테스트"
      ],
      "deliverables": [
        "기본 RAG 파이프라인 실행 스크립트",
        "질문 3건에 대한 초기 답변 결과"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_d1f2eed6c592"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    },
    {
      "phase": 4,
      "phase_name": "근거 추적 및 예외 처리 완성",
      "duration": "1주 (1.5h)",
      "focus_goal": "답변의 근거를 명시하고, 근거 없는 질문을 구분하는 최종 시제품 완성",
      "key_actions": [
        "LLM 답변에 검색된 원문(근거)을 함께 출력하도록 로직 수정",
        "검색 점수 임계값 설정 및 미달 시 '근거 없음/답변 불가' 반환 로직 구현",
        "질문 5건 전체에 대한 최종 테스트 및 결과 분류(성공/누락/불가) 확인"
      ],
      "deliverables": [
        "최종 RAG 시제품 코드",
        "질문 5건별 처리 결과 보고서 (근거 표시 여부, 분류 결과)"
      ],
      "recommended_courses": [
        {
          "course_id": "MS_41fd82f2348f"
        }
      ],
      "recommended_books": [],
      "recommended_certifications": []
    }
  ],
